      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-qwen-studio\",\n  \"version\": \"2.19.2\",\n  \"description\": \"Qwen Image 2.1 for DeepSeek Harness: native reference editing on Apple Silicon MLX and self-hosted CUDA, LoRA, ControlNet, inpainting and live chat progress\",\n  \"type\": \"module\",\n  \"author\": \"kingcharleslzy-ai\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/kingcharleslzy-ai/dsh-qwen-studio.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/kingcharleslzy-ai/dsh-qwen-studio/issues\"\n  },\n  \"homepage\": \"https://github.com/kingcharleslzy-ai/dsh-qwen-studio#readme\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.d.ts\",\n    \"cordis.patch.yml\",\n    \"LICENSE\",\n    \"README.md\",\n    \"backend/server.py\",\n    \"backend/normalize_image.py\",\n    \"scripts/setup-local.sh\",\n    \"skills/**/*.md\",\n    \"docs/*.md\",\n    \"NOTICE\",\n    \"CHANGELOG.md\",\n    \"backend/qwen_gateway.py\",\n    \"backend/qwen_workflow.py\",\n    \"backend/comfy_nodes/**/*.py\",\n    \"LICENSES/*.txt\",\n    \"README.en.md\",\n    \"lib/maintenance.js\",\n    \"bin/*.mjs\",\n    \"scripts/prepare.mjs\",\n    \"AGENTS.md\",\n    \"backend/score_image.py\",\n    \"scripts/npm-command.mjs\",\n    \"scripts/setup-image-python.py\",\n    \"docs/recipes/*.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsc && tsdown\",\n    \"prepare\": \"node scripts/prepare.mjs\",\n    \"test\": \"node scripts/test.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test:worker\": \"node scripts/test-python.mjs\",\n    \"check\": \"npm run typecheck && npm test && npm run test:worker && npm run build\",\n    \"check:package\": \"node scripts/check-package.mjs\",\n    \"check:privacy\": \"node scripts/check-private.mjs\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.1-rc.1 <0.2.2-0 || 0.2.2-rc.1\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"qwen-image\",\n    \"qwen-image-2.1\",\n    \"mlx\",\n    \"mflux\",\n    \"apple-silicon\",\n    \"local-ai\",\n    \"image-generation\",\n    \"text-to-image\",\n    \"image-to-image\",\n    \"lora\",\n    \"controlnet\",\n    \"inpainting\",\n    \"private-gallery\",\n    \"self-hosted\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.0 <5\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.7-rc.2\",\n    \"@deepseek-ai/schemastery\": \">=3.18.4 <4\",\n    \"react\": \">=18.2.0 <19\",\n    \"react-dom\": \">=18.2.0 <19\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"react-dom\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.4\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.7-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.4\",\n    \"@types/cross-spawn\": \"6.0.6\",\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.7\",\n    \"@types/semver\": \"^7.7.0\",\n    \"cross-spawn\": \"7.0.6\",\n    \"lucide-react\": \"^1.38.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.3.1\",\n    \"react-test-renderer\": \"^18.3.1\",\n    \"semver\": \"^7.7.2\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^4.1.8\"\n  },\n  \"packageManager\": \"npm@10.9.8\",\n  \"contributors\": [\n    \"shanliuling (original DSH image-generation integration)\"\n  ],\n  \"bin\": {\n    \"qwen-studio-maintain\": \"bin/qwen-studio-maintain.mjs\"\n  }\n}\n"
    },
