    {
      "path": "src/index.ts",
      "content": "import type { Context } from \"@deepseek-ai/cordis\";\nimport type {} from \"@deepseek-ai/dsh-host-webserver\";\nimport type { IncomingMessage } from \"node:http\";\nimport { readFile, realpath, access } from \"node:fs/promises\";\nimport { GallerySnapshots } from \"./gallery-snapshot.js\";\nimport { PackageInstaller, UpdateController } from \"./updates.js\";\nimport { join, dirname } from \"node:path\";\nimport { Config } from \"./config.js\";\nimport { invocationProgress } from \"./invocations.js\";\nimport { Worker } from \"./worker.js\";\nimport {\n  readJobs,\n  closeGalleryIndexes,\n  restoreGalleryFlags,\n  batchAction,\n  imagePath,\n  validId,\n  type GalleryAction,\n} from \"./storage.js\";\nimport { registerTools } from \"./tools.js\";\nimport { API, active } from \"./shared.js\";\nimport { receiveAsset } from \"./assets.js\";\nimport { resolveConfig } from \"./resolved-config.js\";\nimport { listResources } from \"./resources.js\";\nimport {\n  readPresets,\n  mutatePresets,\n  loadPreset,\n  exportPresets,\n} from \"./presets.js\";\nimport { bundledImageSkill } from \"./skill.js\";\nimport { sshOptions } from \"./remote-lifecycle.js\";\nimport { registerConnectionTool, type ConnectionSettings } from \"./connection-tools.js\";\nexport { Config };\nexport const name = \"qwen-studio\";\nexport const inject = [\"webServer\", \"tools\", \"attachments\"];\nasync function body(req: IncomingMessage, limit = 65536) {\n  const chunks: Buffer[] = [];\n  let size = 0;\n  for await (const chunk of req) {\n    size += chunk.length;\n    if (size > limit) throw Error(\"请求过大\");\n    chunks.push(Buffer.from(chunk));\n  }\n  return JSON.parse(Buffer.concat(chunks).toString(\"utf8\"));\n}\nexport function apply(ctx: Context, config: Config = {}) {\n  const current = () =>\n    Object.fromEntries(\n      Object.entries(config).map(([k, v]) => [\n        k,\n        v && typeof v === \"object\" && \"get\" in v\n          ? (v as { get(): unknown }).get()\n          : v,\n      ]),\n    ) as Config;\n  const worker = new Worker(current);\n  const gallerySnapshots = new GallerySnapshots();\n  ctx.effect(() => () => { void worker.dispose().catch(() => {}); }, \"qwen-studio SSH lifecycle\");\n  let updater: UpdateController | undefined;\n  let updateError = \"\";\n  const updateReady = (async () => {\n    try {\n      const installer = new PackageInstaller();\n      const version = JSON.parse(await readFile(join(installer.paths.packageRoot, \"package.json\"), \"utf8\")).version as string;\n      updater = new UpdateController(installer.paths.state, version, fn => worker.withMaintenance(fn), installer);\n      await updater.init();\n    } catch(e) { updateError = e instanceof Error ? e.message : String(e); }\n  })();\n  ctx.effect(() => () => { updater?.stop(); closeGalleryIndexes(); }, \"qwen-studio updates and gallery index\");\n  registerTools(ctx, worker);\n  (ctx.inject as unknown as (services: string[], callback: (owner: Context) => void) => void)([\"settings\"], (owner) => {\n    registerConnectionTool(owner, worker, owner.get(\"settings\") as ConnectionSettings);\n  });\n  (\n    ctx.inject as unknown as (\n      services: string[],\n      callback: (owner: Context) => void,\n    ) => void\n  )([\"skills\"], (owner) => {\n    const skills = owner.get(\"skills\") as {\n      register(skill: object): () => void;\n    };\n    owner.effect(() => skills.register(bundledImageSkill()), \"图像 skill\");\n  });\n  for (const route of [\n    \"updates\",\n    \"gallery-restore\",\n    \"state\",\n    \"progress\",\n    \"jobs\",\n    \"image\",\n    \"action\",\n    \"check\",\n    \"attachment\",\n    \"assets-upload\",\n    \"settings\",\n    \"resources\",\n    \"presets\",\n  ])\n    ctx.effect(\n      () =>\n        ctx.webServer.register({\n          kind: \"exact\",\n          path: `${API}/${route}`,\n          handler: async (req, res) => {\n            const json = (status: number, value: unknown) => {\n              res.writeHead(status, {\n                \"content-type\": \"application/json\",\n                \"cache-control\": \"no-store\",\n              });\n              res.end(JSON.stringify(value));\n            };\n            try {\n              if (route === \"attachment\" && req.method === \"POST\") {\n                const data = await body(req);\n                const stored = await ctx.attachments.readImage(data.attachment);\n                res.writeHead(200, {\n                  \"content-type\": stored.ref.mediaType,\n                  \"cache-control\": \"private, max-age=86400\",\n                });\n                res.end(stored.data);\n                return;\n              }\n              const dir = worker.directory();\n              if (route === \"updates\") {\n                await updateReady;\n                if(!updater) throw Error(updateError || \"更新服务不可用\");\n                if(req.method === \"GET\") return json(200, { ...updater.snapshot(), backups: await updater.backups() });\n                if(req.method === \"POST\") {\n                  const data = await body(req);\n                  if(data.action === \"preferences\") return json(200, await updater.preferences(data.preferences));\n                  if(data.action === \"check\") return json(200, await updater.check());\n                  if(data.action === \"install\") return json(200, await updater.install());\n                  if(data.action === \"rollback\" && data.confirm === true) return json(200, await updater.rollback(data.id));\n                  throw Error(\"更新操作无效；回滚需要明确确认\");\n                }\n              }\n              if(route === \"gallery-restore\" && req.method === \"POST\") {\n                const data = await body(req);\n                if(data.confirm !== true) throw Error(\"恢复收藏备份需要明确确认\");\n                return json(200, await restoreGalleryFlags(dir));\n              }\n\n              if (route === \"settings\") {\n                const data = req.method === \"POST\" ? await body(req) : {};\n                const effective = resolveConfig({\n                  ...current(),\n                  ...(data.config ?? {}),\n                });\n                if (effective.connectionMode === \"remote\") sshOptions(effective);\n                return json(200, { effective, health: await worker.health() });\n              }\n              if (route === \"resources\" && req.method === \"GET\")\n                return json(200, await listResources(resolveConfig(current())));\n              if (route === \"presets\") {\n                const effective = resolveConfig(current());\n                if (req.method === \"GET\")\n                  return json(200, await readPresets(dir));\n                if (req.method === \"POST\") {\n                  const data = await body(req, 1024 * 1024);\n                  if (data.action === \"load\" || data.action === \"export\") {\n                    const store = await readPresets(dir),\n                      preset = store.items.find((p) => p.id === data.id);\n                    if (data.action === \"export\") {\n                      if(data.id&&!preset)throw Error('预设不存在');\n                      return json(200, exportPresets(store, data.id));\n                    }\n                    if (!preset) throw Error(\"预设不存在\");\n                    return json(200, await loadPreset(effective, preset));\n                  }\n                  return json(200, await mutatePresets(effective, data));\n                }\n              }\n\n              if (route === \"assets-upload\" && req.method === \"POST\") {\n                if (worker.mode() === \"remote\" && !await worker.capabilities())\n                  throw Error(\"该远程服务不支持高级资源，请使用 Qwen 网关\");\n                return json(\n                  201,\n                  await worker.withActivity(() => receiveAsset(\n                    req,\n                    dir,\n                    resolveConfig(current()).pythonPath,\n                  )),\n                );\n              }\n              if (route === \"progress\" && req.method === \"POST\") {\n                const data = await body(req);\n                return json(\n                  200,\n                  await invocationProgress(\n                    dir,\n                    data.call_id ?? \"\",\n                    data.prompt ?? \"\",\n                    Number(data.since ?? 0),\n                    data.session_id ?? \"\",\n                  ),\n                );\n              }\n              if (route === \"state\" && req.method === \"GET\") {\n                await worker.sync();\n                const [jobs, health] = await Promise.all([\n                  readJobs(dir),\n                  worker.health(),\n                ]);\n                // Old interrupted jobs remain visible and retryable even while service is stopped.\n                for (const job of jobs)\n                  if (\n                    active(job) &&\n                    job.worker_pid &&\n                    (job.source === \"remote\" || health.status === \"offline\")\n                  ) {\n                    try {\n                      process.kill(job.worker_pid, 0);\n                    } catch {\n                      job.status = \"failed\";\n                      job.error = \"服务已停止，任务未完成，请重试\";\n                    }\n                  }\n                const prior = new URL(req.url ?? \"\", \"http://localhost\").searchParams.get(\"revision\");\n                return json(200, {\n                  ...gallerySnapshots.project(jobs, prior),\n                  apiVersion: 10,\n                  remoteImageMode: current().remoteImageMode ?? \"quality\",\n                  remoteAdvanced: worker.mode() === \"remote\" && Boolean(await worker.capabilities().catch(() => null)),\n                  referenceEditSupported: (await worker.referenceEditing()).supported,\n                  health:\n                    worker.mode() === \"remote\"\n                      ? { ...health, busy: Boolean(health.busy || worker.remote.size > 0) }\n                      : health,\n                  directory: dir,\n                  idleMinutes: current().localMfluxIdleMinutes ?? 10,\n                  mode: worker.mode(),\n                  configured:\n                    worker.mode() === \"remote\"\n                      ? Boolean(current().remoteBaseURL)\n                      : await Promise.all([\n                          access(resolveConfig(current()).pythonPath),\n                          access(resolveConfig(current()).modelPath),\n                        ])\n                          .then(() => true)\n                          .catch(() => false),\n                });\n              }\n              if (route === \"check\" && req.method === \"POST\")\n                return json(200, await worker.check());\n              if (route === \"jobs\" && req.method === \"POST\")\n                return json(\n                  202,\n                  await worker.post(\"/v1/jobs\", await body(req), true),\n                );\n              if (route === \"action\" && req.method === \"POST\") {\n                const data = await body(req);\n                if (data.action === \"unload\")\n                  return json(200, await worker.post(\"/v1/unload\", {}));\n                if (data.action === \"cancel\") {\n                  if (!validId(data.id ?? \"\")) throw Error(\"任务ID无效\");\n                  return json(\n                    200,\n                    await worker.post(\"/v1/cancel\", { id: data.id }),\n                  );\n                }\n                if (data.action === \"purge\" && data.confirm !== true)\n                  throw Error(\"永久删除需要明确确认\");\n                return json(\n                  200,\n                  await batchAction(\n                    dir,\n                    data.ids ?? [data.id],\n                    data.action as GalleryAction,\n                    data.value,\n                  ),\n                );\n              }\n              if (route === \"image\" && req.method === \"GET\") {\n                const url = new URL(req.url ?? \"\", \"http://localhost\"),\n                  id = url.searchParams.get(\"id\") ?? \"\";\n                if (!validId(id)) throw Error(\"图片ID无效\");\n                let path = await imagePath(dir, id);\n                if (url.searchParams.get(\"reference\") === \"1\") {\n                  const expected = join(dirname(path), \"reference.png\");\n                  path = await realpath(expected);\n                  if (path !== expected) throw Error(\"参考图片路径无效\");\n                }\n                const image = await readFile(path);\n                res.writeHead(200, {\n                  \"content-type\": \"image/png\",\n                  \"cache-control\": \"private, max-age=86400\",\n                  ...(url.searchParams.has(\"download\")\n                    ? {\n                        \"content-disposition\": `attachment; filename=\"qwen-${id.slice(0, 8)}.png\"`,\n                      }\n                    : {}),\n                });\n                res.end(image);\n                return;\n              }\n              json(405, { error: \"不支持的请求\" });\n            } catch (error) {\n              if (!res.headersSent)\n                json(500, {\n                  error: error instanceof Error ? error.message : String(error),\n                });\n            }\n          },\n        }),\n      \"qwen-studio: \" + route,\n    );\n}\n"
    },
    {
      "path": "src/tools.ts",
      "content": "import type { Context } from \"@deepseek-ai/cordis\";\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\nimport type {} from \"@deepseek-ai/dsh-attachment\";\nimport { readFile } from \"node:fs/promises\";\nimport { setTimeout as wait } from \"node:timers/promises\";\nimport { readJob, imagePath } from \"./storage.js\";\nimport { active } from \"./shared.js\";\nimport { recordInvocation } from \"./invocations.js\";\nimport type { Worker } from \"./worker.js\";\nimport { generationParameters } from \"./generation-parameters.js\";\nimport { registerWorkspaceTools } from \"./workspace-tools.js\";\nimport { registerStatusTool } from \"./status-tool.js\";\nimport { registerGalleryTools } from \"./gallery-tool.js\";\nimport { registerBatchTool } from \"./batch-tool.js\";\nimport { registerScoreTool } from \"./score-tool.js\";\nimport { registerRerollTool } from \"./reroll-tool.js\";\nimport { generationPayload, newJobId, validateGeneration } from \"./generation-request.js\";\nexport function registerTools(ctx: Context, worker: Worker) {\n  registerStatusTool(ctx, worker);\n  registerWorkspaceTools(ctx, worker);\n  registerGalleryTools(ctx, worker);\n  registerBatchTool(ctx, worker);\n  registerScoreTool(ctx, worker);\n  registerRerollTool(ctx, worker);\n  ctx.tools.register(\n    defineTool({\n      name: \"qwen_generate_image\",\n      description:\n        \"For a Turbo request use image_mode=turbo on the remote gateway. Default DSH image-generation route: generate with this tool so the conversation, live progress and gallery stay synchronized. Create images with the configured local Qwen Image or self-hosted server. Use for requests to draw, illustrate, make a poster/product image, or generate a picture (画一张、配图、生图). To make a variation of a previous result while retaining its composition, pass that result's source_image_id and change_strength (local or Qwen gateway). Describe the complete desired image, not just an edit instruction. source_image_id alone is strength-based img2img. For style transfer or instruction edits, query capabilities and use reference_mode=edit on supported local MFLUX or an updated Qwen gateway, with full desired edits and no change_strength; legacy variation may reconstruct the original photo. Check qwen_image_resources reference_edit.supported first. Local editing requires MFLUX with QwenImage21Edit and a complete vision-capable checkpoint. Native editing requires linear and dimensions divisible by32, and cannot combine with masks/ControlNet. For a web URL, local file or conversation reference attachment, first call qwen_image_import and use its returned id; no manual gallery import or downloader script is needed. For two to eight reference images in one edit, pass source_image_ids (remote Qwen 2.1 gateway only), reference_mode=edit, and address them as <image1>, <image2>, … in the prompt; do not combine with change_strength, mask or ControlNet. Local and the Qwen gateway support negative_prompt / guidance / scheduler; query qwen_image_resources for remote_capabilities, ordinary Images servers may support text-to-image only. Negative prompts require guidance above 1; the worker uses 2.5 if a negative prompt is supplied with the default guidance. lora_paths / lora_scales stack LoRAs on the base model. controlnet_image_id pins composition and pose from a control image, where structure comes from the control image and content from the prompt. mask_image_id performs masked inpainting over source_image_id: white mask areas are redrawn from the prompt while black areas are copied from the source resized to output dimensions. Returns a visible image attachment plus an id for follow-up variations. Selected Mac assets are synchronized and cached automatically on the configured Qwen gateway; do not invent Windows paths or upload files with scripts. Use qwen_image_resources for real LoRA paths and imported image ids; use qwen_image_presets to list/load/save advanced settings. Preset configuration alone must not trigger generation. No shell, manual server startup, file search, or manual skill installation is needed. If an accepted task times out, query qwen_image_status with its full id; never resubmit or switch to a standalone script automatically.\",\n      timeoutMs: 1200000,\n      parameters: generationParameters,\n      output: {\n        schema: {\n          type: \"object\",\n          additionalProperties: false,\n          properties: {\n            id: { type: \"string\", required: true },\n            attachment: {\n              type: \"object\",\n              required: true,\n              additionalProperties: false,\n              properties: {\n                attachmentId: { type: \"string\", required: true },\n                mediaType: { type: \"string\", required: true },\n                bytes: { type: \"integer\", required: true },\n                width: { type: \"integer\", required: true },\n                height: { type: \"integer\", required: true },\n                name: { type: \"string\" },\n                originalDimensions: {\n                  type: \"object\",\n                  additionalProperties: false,\n                  properties: {\n                    width: { type: \"integer\", required: true },\n                    height: { type: \"integer\", required: true },\n                  },\n                },\n              },\n            },\n          },\n        },\n        presentationMeta: (args, value) => ({\n          kind: \"qwen-studio\",\n          id: value.id,\n          prompt: args.prompt,\n          attachment: value.attachment,\n        }),\n        render: (_args, value) => [\n          {\n            type: \"text\",\n            text: `图像任务${value.id}已完成。图片已自动入库并附在对话中，无需搜索或重新读取。`,\n          },\n          {\n            type: \"image\",\n            attachment:\n              value.attachment as import(\"@deepseek-ai/dsh-attachment\").ImageAttachmentRef,\n          },\n        ],\n      },\n      async execute(args, exec) {\n        validateGeneration(args);\n        const id = newJobId(),\n          dir = worker.directory();\n        await recordInvocation(\n          dir,\n          exec.callId,\n          args.prompt,\n          id,\n          undefined,\n          exec.agent?.id ?? \"\",\n        );\n        try {\n          await worker.post(\"/v1/jobs\", generationPayload(args, id), true);\n        } catch (error) {\n          await recordInvocation(\n            dir,\n            exec.callId,\n            args.prompt,\n            id,\n            error instanceof Error ? error.message : String(error),\n            exec.agent?.id ?? \"\",\n          );\n          throw Error(`提交任务 ${id} 未确认：${error instanceof Error ? error.message : String(error)}。先用 qwen_image_status 查询该 ID，勿自动重试或运行脚本。`);\n        }\n        const started = Date.now();\n        while (Date.now() - started < 20 * 60 * 1000) {\n          if (exec.signal.aborted)\n            throw Error(`等待已取消，任务 ${id} 仍保留；用 qwen_image_status 查询或在图像中取消。`);\n          const job = await readJob(dir, id);\n          if (job && !active(job)) {\n            if (job.status !== \"complete\")\n              throw Error(`任务 ${id}：${job.error ?? job.status}。可用 qwen_image_status 查看，勿自动换脚本或重复提交。`);\n            const data = await readFile(await imagePath(dir, id));\n            const attachment = await ctx.attachments.saveImage({\n              data,\n              mediaType: \"image/png\",\n              name: `qwen-${id.slice(0, 8)}.png`,\n            });\n            return { id, attachment };\n          }\n          try { await wait(1000, undefined, { signal: exec.signal }); }\n          catch { throw Error(`等待已取消，任务 ${id} 仍保留；用 qwen_image_status 查询或在图像中取消。`); }\n        }\n        throw Error(\n          `等待超时，任务 ${id} 仍保留；用 qwen_image_status 查询，不要重复提交或改跑脚本。`,\n        );\n      },\n      presentResult: (_args, result) => ({\n        card: \"generic\",\n        title: \"图像\",\n        content: result.content,\n      }),\n    }),\n  );\n}\n"
    },
    {
      "path": "src/worker.ts",
      "content": "import { spawn, execFile } from \"node:child_process\";\nimport { promisify } from \"node:util\";\nimport { openSync, closeSync } from \"node:fs\";\nimport { access, readFile, mkdir } from \"node:fs/promises\";\nimport { resolve, join, dirname } from \"node:path\";\nimport { resolveConfig } from \"./resolved-config.js\";\nimport { fileURLToPath } from \"node:url\";\nimport { copyFile } from \"node:fs/promises\";\nimport { RemoteQueue, remoteURL, headers } from \"./remote.js\";\nimport { readJobs } from \"./storage.js\";\nimport { atomicJSON } from \"./storage.js\";\nimport { upgradeIdleWorker } from \"./worker-upgrade.js\";\nimport type { Config } from \"./config.js\";\nimport type { Health } from \"./shared.js\";\nimport { RemoteLifecycle, SshTunnel, sshOptions } from \"./remote-lifecycle.js\";\nimport { requiredFeatures, type RemoteCapabilities } from \"./remote-protocol.js\";\nconst BASE = \"http://127.0.0.1:19388\";\nconst exec = promisify(execFile);\nexport interface ReferenceEditing { supported: boolean; reason?: string; mflux_version?: string; verification?: string }\nexport class Worker {\n  readonly remote = new RemoteQueue();\n  transportConfig(): Config {\n    return { ...this.config(), ...resolveConfig(this.config()) };\n  }\n  mode() {\n    return resolveConfig(this.config()).connectionMode;\n  }\n  private starting: Promise<void> | undefined;\n  private editProbe?: { key: string; expires: number; value: Promise<ReferenceEditing> };\n  async referenceEditing(): Promise<ReferenceEditing> {\n    if (this.mode() === \"remote\") return { supported: Boolean((await this.capabilities().catch(() => null))?.features.includes(\"reference_edit\")), verification: this.managedSSH() ? \"on_generation\" : \"handshake\" };\n    const { pythonPath, modelPath } = resolveConfig(this.config()), key = JSON.stringify([pythonPath, modelPath]);\n    if (this.editProbe?.key === key && this.editProbe.expires > Date.now()) return this.editProbe.value;\n    const bundled = resolve(dirname(fileURLToPath(import.meta.url)), \"../backend/server.py\");\n    const value = exec(pythonPath, [bundled, \"--check-reference-edit\", modelPath], {\n      timeout: 15000, maxBuffer: 65536, env: { ...process.env, HF_HUB_OFFLINE: \"1\" },\n    }).then(({ stdout }) => {\n      const result = JSON.parse(stdout.trim()) as ReferenceEditing;\n      if (typeof result.supported !== \"boolean\") throw Error(\"MFLUX 能力检测响应无效\");\n      return result;\n    }).catch((e: Error) => ({ supported: false, reason: `本机原生编辑检查失败：${e.message}` }));\n    this.editProbe = { key, expires: Date.now() + 30000, value }; return value;\n  }\n  private modeGate: Promise<unknown> = Promise.resolve();\n  private serialized<T>(fn: () => Promise<T>) {\n    const result = this.modeGate.then(fn); this.modeGate = result.catch(() => {}); return result;\n  }\n  switchConnection(mode: \"local\" | \"remote\", persist: () => Promise<void>) {\n    return this.serialized(async () => {\n      if (mode === this.mode()) return;\n      if (this.remote.size) throw Error(\"有远程任务正在上传、排队或生成，结束后再切换\");\n      // Also protect a local worker left running by a previous process.\n      try {\n        const r = await fetch(BASE + \"/health\", { signal: AbortSignal.timeout(1500) });\n        if (r.ok && (await r.json() as Health).busy) throw Error(\"有本机生图任务正在运行，结束后再切换\");\n      } catch (e) { if (e instanceof Error && e.message.includes(\"本机生图任务\")) throw e; }\n      if (mode === \"local\") {\n        const local = resolveConfig(this.config()); await access(local.pythonPath); await access(local.modelPath);\n      } else {\n        remoteURL(this.transportConfig()); sshOptions(this.transportConfig());\n      }\n      if (this.mode() === \"remote\" && this.managedSSH()) await this.lifecycle.unload();\n      if (this.mode() === \"local\") {\n        const health = await this.health();\n        if (health.status === \"ok\") await this.post(\"/v1/unload\", {});\n      }\n      await persist();\n      if (this.mode() !== mode) throw Error(\"宿主尚未确认运行位置更新，请重新读取状态\");\n    });\n  }\n  private settingsKey = \"\";\n  readonly lifecycle: RemoteLifecycle;\n  constructor(private config: () => Config) {\n    this.lifecycle = new RemoteLifecycle(() => this.transportConfig(), new SshTunnel(), {\n      configure: (c, seconds) => this.configureRemote(c, seconds),\n      unload: (c) => this.unloadRemote(c),\n    });\n  }\n  managedSSH() { return this.mode() === \"remote\" && Boolean(this.transportConfig().remoteSshHost?.trim()); }\n  async capabilities(): Promise<RemoteCapabilities | null> {\n    if (this.managedSSH() && !this.lifecycle.connected) {\n      sshOptions(this.transportConfig());\n      // Configured Qwen protocol contract; actual handshake is mandatory at submission.\n      // Passive reads must never create an SSH connection.\n      return { protocol: \"dsh-qwen\", version: 1, features: [...requiredFeatures, \"reference_edit\", \"multi_image\"], schedulers: [\"linear\", \"flow_match_euler_discrete\", \"seedvr2_euler\"], verification: \"on_generation\" } as RemoteCapabilities;\n    }\n    return this.remote.capabilities(this.transportConfig());\n  }\n  private async configureRemote(config: Config, seconds: number) {\n    const r = await fetch(remoteURL(config) + \"/qwen/runtime-config\", { method: \"POST\", headers: headers(config), body: JSON.stringify({ idle_seconds: seconds }), signal: AbortSignal.timeout(5000), redirect: \"error\" });\n    if (!r.ok) throw Error(`远程空闲设置失败：HTTP ${r.status}；请更新配套 Qwen 网关`);\n    const value = await r.json() as { idle_seconds?: number };\n    if (value.idle_seconds !== seconds) throw Error(\"远程空闲时间未确认，请检查网关版本\");\n  }\n  private async unloadRemote(config: Config) {\n    const r = await fetch(remoteURL(config) + \"/qwen/unload\", { method: \"POST\", headers: headers(config), body: \"{}\", signal: AbortSignal.timeout(45000), redirect: \"error\" });\n    if (!r.ok || !(await r.json() as { unloaded?: boolean }).unloaded) throw Error(\"远程仍有任务或模型卸载未确认；保留连接稍后重试\");\n    const h = await fetch(remoteURL(config) + \"/qwen/health\", { headers: headers(config), signal: AbortSignal.timeout(5000), redirect: \"error\" });\n    if (!h.ok) throw Error(\"未能核对远程模型已卸载，保留连接\");\n    const health = await h.json() as Health;\n    if (health.loaded || health.busy) throw Error(\"远程仍有任务或模型尚未退出，保留连接\");\n  }\n  async dispose() { await this.remote.dispose(); await this.lifecycle.dispose(); }\n  directory() {\n    return resolveConfig(this.config()).localMfluxDirectory;\n  }\n\n  async sync() {\n    const effective = resolveConfig(this.config()),\n      dir = effective.localMfluxDirectory,\n      minutes = effective.localMfluxIdleMinutes,\n      loraDirectory = effective.loraDirectory;\n    const key = JSON.stringify([dir, minutes, loraDirectory]);\n    if (key === this.settingsKey) return;\n    await mkdir(join(dir, \"state\"), { recursive: true });\n    await atomicJSON(join(dir, \"state/runtime-config.json\"), {\n      idle_seconds: Math.round(minutes * 60),\n      lora_directory: loraDirectory,\n    });\n    this.settingsKey = key;\n  }\n  async health(): Promise<Health> {\n    try {\n      if (this.mode() === \"remote\") {\n        if (this.managedSSH() && !this.lifecycle.connected) return { status: \"remote\", loaded: false, busy: this.remote.size > 0, ssh_status: \"disconnected\" };\n        if (!await this.capabilities()) return { status: \"remote\", busy: this.remote.size > 0 };\n        const r = await fetch(remoteURL(this.transportConfig()) + \"/qwen/health\", { headers: headers(this.transportConfig()), signal: AbortSignal.timeout(2000), redirect: \"error\" });\n        if (!r.ok) throw Error(\"远程状态不可用\");\n        return { ...await r.json() as Health, status: \"remote\", ...(this.managedSSH() ? { ssh_status: \"connected\", ...(this.lifecycle.remaining !== undefined ? { idle_remaining_seconds: this.lifecycle.remaining } : {}), connection_error: this.lifecycle.error } : {}) };\n      }\n      const r = await fetch(BASE + \"/health\", {\n        signal: AbortSignal.timeout(1500),\n      });\n      if (!r.ok) throw Error();\n      return (await r.json()) as Health;\n    } catch {\n      return { status: \"offline\" };\n    }\n  }\n  async ensure() {\n    if (!this.starting)\n      this.starting = this.start().finally(() => {\n        this.starting = undefined;\n      });\n    return this.starting;\n  }\n  private async start() {\n    await this.sync();\n    let h = await upgradeIdleWorker(\n      await this.health(),\n      () => this.post(\"/v1/unload\", {}),\n      () => this.health(),\n    );\n    if (h.status === \"ok\" && !h.closing) {\n      if (h.version !== 8)\n        throw Error(\"旧版生图服务尚未退出，请等待空闲卸载后重试\");\n      return;\n    }\n    // A worker can be in the last milliseconds of idle shutdown.\n    for (let n = 0; h.closing && n < 20; n++) {\n      await new Promise((r) => setTimeout(r, 200));\n      h = await this.health();\n    }\n    const dir = this.directory(),\n      python = resolveConfig(this.config()).pythonPath;\n    const model = resolveConfig(this.config()).modelPath;\n    await access(model);\n    const bundled = resolve(\n      dirname(fileURLToPath(import.meta.url)),\n      \"../backend/server.py\",\n    );\n    await copyFile(bundled, join(dir, \"server.py\"));\n    await access(python);\n    const fd = openSync(join(dir, \"state/service.log\"), \"a\", 0o600);\n    const child = spawn(python, [\"-u\", join(dir, \"server.py\")], {\n      cwd: dir,\n      stdio: [\"ignore\", fd, fd],\n      env: {\n        ...process.env,\n        HF_HUB_OFFLINE: \"1\",\n        QWEN_DATA_DIR: dir,\n        QWEN_MODEL_PATH: model,\n        HF_HOME: resolveConfig(this.config()).hfHome,\n      },\n    });\n    closeSync(fd);\n    child.unref();\n    let error: Error | undefined;\n    child.once(\"error\", (e) => {\n      error = e;\n    });\n    for (let i = 0; i < 100; i++) {\n      if (error) throw error;\n      if (child.exitCode !== null)\n        throw Error(\"本地服务启动失败，请查看service.log\");\n      h = await this.health();\n      if (h.status === \"ok\" && h.version === 8 && !h.closing) return;\n      await new Promise((r) => setTimeout(r, 150));\n    }\n    throw Error(\"本地服务启动超时\");\n  }\n\n  async check() {\n    if (this.mode() === \"remote\") {\n      if (this.managedSSH() && !this.lifecycle.connected) {\n        sshOptions(this.transportConfig());\n        return { ok: true, message: \"按需 SSH 配置格式有效。当前未连接；真正提交生图时才建立连接并验证服务器，不启动模型。\" };\n      }\n      const response = await fetch(\n        remoteURL(this.transportConfig()) + \"/models\",\n        {\n          headers: headers(this.transportConfig()),\n          signal: AbortSignal.timeout(8000),\n          redirect: \"error\",\n        },\n      );\n      if (!response.ok) throw Error(`远程连接失败：HTTP ${response.status}`);\n      const data = (await response.json()) as { data?: { id: string }[] };\n      const advanced = await this.remote.capabilities(this.transportConfig());\n      return {\n        ok: true,\n        message: advanced ? \"Qwen 远程网关可达；支持 LoRA、结构控制、蒙版、参考变体和真实步数进度。\" : \"远程接口可达；基础 Images API，仅支持文生图。\",\n        models: data.data?.map((m) => m.id) ?? [],\n      };\n    }\n    const dir = this.directory(),\n      python = resolveConfig(this.config()).pythonPath,\n      model = resolveConfig(this.config()).modelPath;\n    await access(python);\n    try {\n      await Promise.any(\n        [\"model_index.json\", \"config.json\", \"transformer/config.json\"].map(\n          (file) => access(join(model, file)),\n        ),\n      );\n    } catch {\n      throw Error(\n        \"模型目录中未找到model_index.json或模型配置文件，请选择完整的Qwen模型目录\",\n      );\n    }\n    return {\n      ok: true,\n      message: \"Python与模型目录存在。首次生成会验证MFLUX及模型组件。\",\n      python,\n      model,\n    };\n  }\n  private transfers = 0;\n  private maintenance = false;\n  private retired = false;\n  async withActivity<T>(fn: () => Promise<T>): Promise<T> {\n    if (this.maintenance || this.retired) throw Error(\"插件正在维护或等待手动重启，请稍后再试\");\n    this.transfers++;\n    try { return await fn(); } finally { this.transfers--; }\n  }\n  withMaintenance<T>(fn: () => Promise<T>): Promise<T> {\n    return this.serialized(async () => {\n      if (this.transfers || this.remote.size) throw Error(\"正在上传、排队或生成，更新已延后；任务结束后重试\");\n      this.maintenance = true;\n      try {\n        // Check both backends, including a local worker left by another process.\n        if ((await readJobs(this.directory())).some(j => [\"queued\",\"uploading\",\"loading\",\"running\",\"saving\",\"cancelling\"].includes(j.status))) throw Error(\"图库仍有未结束任务，更新已延后\");\n        const current = await this.health();\n        if (current.busy) throw Error(\"生图服务正在工作，更新已延后\");\n        let localBusy = false;\n        try { const r = await fetch(BASE + \"/health\", { signal: AbortSignal.timeout(1500) }); if(r.ok) localBusy = Boolean((await r.json() as Health).busy); } catch {}\n        if(localBusy) throw Error(\"本机仍有生图任务，更新已延后\");\n        const result = await fn(); this.retired = true; return result;\n      } finally { this.maintenance = false; }\n    });\n  }\n  async post(path: string, data: unknown, start = false) {\n    if (start) return this.serialized(() => this.withActivity(() => this.submit(path, data)));\n    return this.submit(path, data, false);\n  }\n  private async submit(path: string, data: unknown, start = true) {\n    if (path === \"/v1/jobs\" && this.mode() === \"local\" && data && typeof data === \"object\" && \"image_mode\" in data) {\n      if (data.image_mode !== \"quality\") throw Error(\"Turbo 仅支持远程 Qwen 网关；请在图像设置里选择远程。\");\n      const { image_mode, ...local } = data;\n      data = local;\n    }\n    const referenceMode = (data as Record<string, unknown>)?.reference_mode;\n    const sourceIds = (data as Record<string, unknown>)?.source_image_ids;\n    if (path === \"/v1/jobs\" && Array.isArray(sourceIds) && sourceIds.length && this.mode() !== \"remote\")\n      throw Error(\"多图参考仅支持已更新的远程 Qwen 网关；本机请用单张 source_image_id\");\n    if (path === \"/v1/jobs\" && referenceMode === \"edit\" && this.mode() === \"local\") {\n      const support = await this.referenceEditing();\n      if (!support.supported) throw Error(support.reason || \"当前本机 MFLUX 或模型不支持原生参考编辑；不会自动切换后端\");\n    }\n    if (start && this.mode() === \"remote\") {\n      const config = this.transportConfig();\n      let release: (() => void) | undefined;\n      try {\n        if (this.managedSSH()) release = await this.lifecycle.acquire(config);\n        else if (await this.capabilities()) await this.configureRemote(config, Math.round((config.localMfluxIdleMinutes ?? 10) * 60));\n        return await this.remote.submit(this.directory(), config, data as Record<string, unknown>, release, this.managedSSH() ? () => this.lifecycle.reconnect(config) : undefined);\n      } catch (e) { release?.(); throw e; }\n    }\n    if (path === \"/v1/unload\" && this.mode() === \"remote\") {\n      if (this.managedSSH()) { await this.lifecycle.unload(); return { unloaded: true, disconnected: true }; }\n      if (!await this.remote.capabilities(this.transportConfig())) throw Error(\"普通远程接口不支持释放模型\");\n      const r = await fetch(remoteURL(this.transportConfig()) + \"/qwen/unload\", { method: \"POST\", headers: headers(this.transportConfig()), body: \"{}\", signal: AbortSignal.timeout(45000), redirect: \"error\" });\n      if (!r.ok) throw Error(\"远程仍有任务或释放失败，请查询当前任务状态\");\n      return r.json();\n    }\n    if (path === \"/v1/cancel\") {\n      const id = (data as { id: string }).id;\n      const job = (await readJobs(this.directory())).find((j) => j.id === id);\n      if (job?.source === \"remote\") return this.remote.cancel(id);\n    }\n    if (start) await this.ensure();\n    const token = (\n      await readFile(join(this.directory(), \"state/api-key\"), \"utf8\")\n    ).trim();\n    const response = await fetch(BASE + path, {\n      method: \"POST\",\n      headers: {\n        \"content-type\": \"application/json\",\n        authorization: `Bearer ${token}`,\n      },\n      body: JSON.stringify(data),\n      signal: AbortSignal.timeout(10000),\n    });\n    const value = (await response.json()) as { error?: string };\n    if (!response.ok) throw Error(value.error ?? \"本地任务请求失败\");\n    return value;\n  }\n}\n"
    },
