h != null || data.reference_mode != null))\n      throw Error(\n        \"当前远程接口仅支持文生图，不能忽略参考图继续生成；请切换本地模式或移除参考图\",\n      );\n    if (!capabilities && (\n      data.negative_prompt != null ||\n      data.guidance != null ||\n      data.scheduler != null\n    ))\n      throw Error(\n        \"负向提示词、CFG 与调度器目前仅接入本地模式；远程接口不会忽略这些参数继续生成\",\n      );\n    if (!capabilities && [\"lora_paths\", \"lora_scales\", \"controlnet_image_id\", \"controlnet_strength\", \"mask_image_id\"].some(key => data[key] !== undefined))\n      throw Error(\"LoRA、ControlNet 与蒙版目前仅支持本地模式；远程不会忽略这些参数继续生成\");\n    remoteURL(config);\n    const id = data.id as string;\n    if (!validId(id)) throw Error(\"任务ID无效\");\n    const prompt = data.prompt,\n      width = data.width ?? 1024,\n      height = data.height ?? 1024,\n      steps = mode === \"turbo\" ? 8 : data.steps ?? 40,\n      seed = data.seed ?? null;\n    if (typeof prompt !== \"string\" || !prompt.trim() || prompt.length > 16000)\n      throw Error(\"请填写1–16000字的描述\");\n    if (\n      [width, height].some(\n        (v) =>\n          typeof v !== \"number\" ||\n          !Number.isInteger(v) ||\n          v < 512 ||\n          v > 2048 ||\n          v % 16,\n      )\n    )\n      throw Error(\"尺寸无效\");\n    if (\n      typeof steps !== \"number\" ||\n      !Number.isInteger(steps) ||\n      steps < 1 ||\n      steps > 60\n    )\n      throw Error(\"步数应为1–60\");\n    if (\n      seed !== null &&\n      (typeof seed !== \"number\" ||\n        !Number.isInteger(seed) ||\n        seed < 0 ||\n        seed >= 2 ** 32)\n    )\n      throw Error(\"种子无效\");\n    const advanced = capabilities ? advancedParameters(data, capabilities) : {};\n    const request = {\n        ...advanced,\n        ...(mode === \"turbo\" ? { image_mode: \"turbo\" as const } : {}),\n        prompt,\n        width: width as number,\n        height: height as number,\n        steps,\n        seed,\n      },\n      folder = join(dir, \"images\", id),\n      file = join(folder, \"job.json\");\n    try {\n      const old = JSON.parse(await readFile(file, \"utf8\"));\n      if (JSON.stringify(old.request) !== JSON.stringify(request))\n        throw Error(\"任务ID参数冲突\");\n      settled?.();\n      return old;\n    } catch (e) {\n      if ((e as NodeJS.ErrnoException).code !== \"ENOENT\") throw e;\n    }\n    if (this.pending.size >= 4) throw Error(\"远程队列已满\");\n    const job = {\n      id,\n      ...request,\n      seed: seed ?? Math.floor(Math.random() * 2 ** 32),\n      status: \"queued\",\n      source: \"remote\" as const,\n      progress_supported: Boolean(capabilities),\n      started_at: Date.now() / 1000,\n      worker_pid: process.pid,\n      request,\n    };\n    await mkdir(folder, { recursive: true });\n    await atomicJSON(file, job);\n    this.pending.set(id, new AbortController());\n    this.configs.set(id, { dir, config: { ...config }, settled, reconnect });\n    this.tail = this.tail.then(() => this.run(job as Job)).catch(() => {});\n    return job;\n  }\n  private async run(job: Job) {\n    const controller = this.pending.get(job.id)!,\n      { dir, config, settled, reconnect } = this.configs.get(job.id)!,\n      folder = join(dir, \"images\", job.id),\n      file = join(folder, \"job.json\"),\n      start = Date.now();\n    const timer = setTimeout(\n      () => controller.abort(Error(\"远程生成超过30分钟\")),\n      30 * 60 * 1000,\n    );\n    const patch = async (value: object) => {\n      const old = JSON.parse(await readFile(file, \"utf8\"));\n      await atomicJSON(file, { ...old, ...value });\n    };\n    let extendedAccepted = false;\n    let extended = false;\n    try {\n      controller.signal.throwIfAborted();\n      extended = Boolean(await this.capabilities(config));\n      await patch({ status: \"running\" });\n      let bytes: Buffer;\n      if (job.image_mode === \"turbo\" && !extended) throw Error(\"远程 Turbo 能力不可用\");\n      if (extended) {\n        bytes = await runExtended({ base: remoteURL(config), headers: headers(config), dir, config, job, signal: controller.signal, patch, reconnect, accepted: () => { extendedAccepted = true; } });\n      } else {\n      const response = await fetch(remoteURL(config) + \"/images/generations\", {\n        method: \"POST\",\n        headers: headers(config),\n        redirect: \"error\",\n        signal: controller.signal,\n        body: JSON.stringify({\n          model: config.remoteModel || \"qwen-image\",\n          prompt: job.prompt,\n          size: `${job.width}x${job.height}`,\n          n: 1,\n          response_format: \"b64_json\",\n          seed: job.seed,\n          num_inference_steps: job.steps,\n        }),\n      });\n      if (!response.ok)\n        throw Error(\n          `远程服务返回HTTP ${response.status}，请检查服务日志或接口配置`,\n        );\n      const payload = (await response.json()) as {\n        data?: { b64_json?: string; url?: string }[];\n      };\n      const item = payload.data?.[0];\n      if (!item?.b64_json)\n        throw Error(\n          \"远程接口需返回 data[0].b64_json（PNG），当前不支持图片URL返回\",\n        );\n      bytes = Buffer.from(item.b64_json, \"base64\");\n      }\n      if (\n        bytes.length > 64 * 1024 * 1024 ||\n        bytes.length < 24 ||\n        !bytes\n          .subarray(0, 8)\n          .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))\n      )\n        throw Error(\"远程返回不是有效PNG或超过64MB\");\n      controller.signal.throwIfAborted();\n      await patch({ status: \"saving\" });\n      await writeFile(join(folder, \"image.pending.png\"), bytes);\n      await rename(\n        join(folder, \"image.pending.png\"),\n        join(folder, \"image.png\"),\n      );\n      await patch({\n        status: \"complete\",\n        width: bytes.readUInt32BE(16),\n        height: bytes.readUInt32BE(20),\n        step: extended ? JSON.parse(await readFile(file, \"utf8\")).sampling_steps ?? job.steps : job.steps,\n        elapsed_seconds: Math.round((Date.now() - start) / 10) / 100,\n      });\n    } catch (e) {\n      if (controller.signal.aborted && extended && extendedAccepted) {\n        try {\n          await fetch(remoteURL(config) + \"/qwen/jobs/\" + job.id + \"/cancel\", { method: \"POST\", headers: headers(config), redirect: \"error\", signal: AbortSignal.timeout(5000) });\n        } catch { /* The local cancellation still records that remote acknowledgement was lost. */ }\n      }\n      await patch({\n        status: controller.signal.aborted ? \"cancelled\" : \"failed\",\n        error: controller.signal.aborted\n          ? extended ? \"已停止等待并请求取消远程任务；连接中断时请检查远程状态\" : \"已停止等待；远程服务可能仍在计算\"\n          : e instanceof Error\n            ? e.message\n            : String(e),\n      });\n    } finally {\n      clearTimeout(timer);\n      this.pending.delete(job.id);\n      this.configs.delete(job.id);\n      settled?.();\n    }\n  }\n  cancel(id: string) {\n    const controller = this.pending.get(id);\n    if (!controller) throw Error(\"远程任务已结束或当前DSH进程不持有该任务\");\n    controller.abort();\n    return { ok: true };\n  }\n  get size() {\n    return this.pending.size;\n  }\n  async dispose() {\n    this.disposed = true;\n    await this.admission;\n    for (const controller of this.pending.values()) controller.abort();\n    await this.tail;\n  }\n}\n"
